// Generated by scripts/gen-buildinfo.sh. DO NOT EDIT.
// Stamped from git on every `make build`; a modified copy in the tree is
// expected and harmless (it just means you built since the last commit).
import Foundation

public enum BuildInfo {
    /// Short hash of HEAD when this binary was built.
    public static let commit = "2b9408e04"
    /// Commit date of HEAD (YYYY-MM-DD).
    public static let commitDate = "2026-08-30"
    /// Branch HEAD was on at build time.
    public static let branch = "perf-presentation-overhaul"
    /// True when the working tree had uncommitted changes at build time.
    public static let dirty = false

    /// When this executable was actually built, read from its own file date.
    public static let builtAt: Date? = {
        guard let path = Bundle.main.executableURL?.path,
              let attrs = try? FileManager.default.attributesOfItem(atPath: path),
              let date = attrs[.modificationDate] as? Date else { return nil }
        return date
    }()

    /// e.g. "0.3.0 · a1b2c3d4e · built Aug 29, 14:32"
    public static var summary: String {
        var s = "\(AppIdentity.version) · \(commit)\(dirty ? "+" : "")"
        if let built = builtAt {
            let f = DateFormatter()
            f.dateFormat = "MMM d, HH:mm"
            s += " · built \(f.string(from: built))"
        }
        return s
    }

    /// Longer form for tooltips / the About panel.
    public static var detail: String {
        var parts = ["commit \(commit)\(dirty ? " (modified)" : "")"]
        if !branch.isEmpty, branch != "HEAD" { parts.append("branch \(branch)") }
        if !commitDate.isEmpty { parts.append(commitDate) }
        return parts.joined(separator: " · ")
    }
}
